-- SsoState
ALTER TABLE "SsoState" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "SsoState" FORCE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS org_isolation ON "SsoState";
DROP POLICY IF EXISTS org_insert ON "SsoState";
DROP POLICY IF EXISTS org_select ON "SsoState";
DROP POLICY IF EXISTS org_update ON "SsoState";
DROP POLICY IF EXISTS org_delete ON "SsoState";
CREATE POLICY org_isolation ON "SsoState" FOR ALL USING ("orgId" = nullif(current_setting('app.org_id', true), '')::uuid) WITH CHECK ("orgId" = nullif(current_setting('app.org_id', true), '')::uuid);
